import AppKit
import SwiftUI

enum BrowserIconProvider {
    private static let cache = NSCache<NSString, NSImage>()

    static func image(for id: String) -> Image {
        Image(nsImage: nsImage(for: id))
            .interpolation(.high)
            .resizable()
    }

    static func nsImage(for id: String) -> NSImage {
        let key = id as NSString
        if let cached = cache.object(forKey: key) {
            return cached
        }

        let img = loadIcon(for: id)
        cache.setObject(img, forKey: key)
        return img
    }

    private static func loadIcon(for id: String) -> NSImage {
        if id == "lean" {
            if let url = Bundle.main.url(forResource: "lean", withExtension: "icns"),
               let img = NSImage(contentsOf: url) {
                img.size = NSSize(width: 64, height: 64)
                return img
            }
            if let appIcon = NSApplication.shared.applicationIconImage, appIcon.isValid {
                appIcon.size = NSSize(width: 64, height: 64)
                return appIcon
            }
            if let img = NSImage(named: "lean") {
                img.size = NSSize(width: 64, height: 64)
                return img
            }
            for path in ["icons/browsers/lean.png", "/Users/dipxsy/Code/projects/browser/icons/browsers/lean.png"] {
                if FileManager.default.fileExists(atPath: path),
                   let img = NSImage(contentsOfFile: path) {
                    img.size = NSSize(width: 64, height: 64)
                    return img
                }
            }
        }

        let candidates: [String] = {
            switch id {
            case "arc": return ["/Applications/Arc.app"]
            case "dia": return ["/Applications/Dia.app"]
            case "helium": return ["/Applications/Helium.app"]
            case "chrome": return ["/Applications/Google Chrome.app", "/Applications/Chrome.app"]
            case "safari": return ["/Applications/Safari.app", "/System/Applications/Safari.app"]
            default: return []
            }
        }()

        for path in candidates {
            if FileManager.default.fileExists(atPath: path) {
                let icon = NSWorkspace.shared.icon(forFile: path)
                icon.size = NSSize(width: 64, height: 64)
                return icon
            }
        }

        if let b64 = base64Data[id],
           let data = Data(base64Encoded: b64),
           let img = NSImage(data: data) {
            img.size = NSSize(width: 64, height: 64)
            return img
        }

        return NSImage(systemSymbolName: "globe", accessibilityDescription: nil) ?? NSImage()
    }

    private static let base64Data: [String: String] = [
        "lean": "",
        "arc": "",
        "dia": "",
        "helium": "",
        "chrome": "",
        "safari": "",
    ]
}
